/* Landing page — small coffee roastery in Brno.
 * opt_out: palette — a warm roast palette lives in the .lp namespace below;
 * type, radii, spacing and motion stay on the maude tokens.
 * One page, three artboards: reflow is by container width (@container lp),
 * never by viewport units. */

.lp {
  /* roast palette (local namespace) */
  --lp-cream:    oklch(0.965 0.016 82);
  --lp-cream-2:  oklch(0.820 0.030 78);
  --lp-paper:    oklch(0.935 0.026 80);
  --lp-crema:    oklch(0.865 0.060 72);
  --lp-latte:    oklch(0.760 0.075 62);
  --lp-ink:      oklch(0.250 0.030 50);
  --lp-ink-2:    oklch(0.420 0.035 55);
  --lp-roast:    oklch(0.340 0.060 45);
  --lp-espresso: oklch(0.215 0.028 48);
  --lp-clay:     oklch(0.500 0.125 42);
  --lp-clay-hi:  oklch(0.450 0.125 42);
  --lp-line:     oklch(0.860 0.025 78);

  container-type: inline-size;
  container-name: lp;
  width: 100%;
  background: var(--lp-cream);
  color: var(--lp-ink);
  font-family: var(--font-body);
  font-size: var(--type-md);
  line-height: var(--lh-md);
}

.lp *, .lp *::before, .lp *::after { box-sizing: border-box; }
.lp h1, .lp h2, .lp h3, .lp p, .lp ol, .lp dl, .lp dd { margin: 0; padding: 0; }
.lp ol { list-style: none; }
.lp a { color: inherit; text-decoration: none; }

/* every section shares the same side gutter */
.lp-hd, .lp-hero, .lp-facts, .lp-coffees, .lp-story, .lp-sub, .lp-visit, .lp-ft {
  padding-inline: max(var(--space-6), 6cqi);
}

/* ── type ─────────────────────────────────────────────────────────────── */
.lp-eyebrow {
  font-family: var(--font-mono);
  font-size: var(--type-sm);
  line-height: var(--lh-sm);
  letter-spacing: var(--tracking-wide);
  text-transform: uppercase;
  color: var(--lp-clay);
  font-weight: var(--weight-medium);
}
.lp-h1, .lp-h2, .lp-h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-tight);
  font-weight: var(--weight-semibold);
  color: inherit;
}
.lp-h1 { font-size: calc(var(--type-3xl) * 2); line-height: 1.04; text-wrap: balance; }
.lp-h2 { font-size: calc(var(--type-3xl) * 1.2); line-height: 1.1; text-wrap: balance; }
.lp-h3 { font-size: var(--type-lg); line-height: var(--lh-lg); }
.lp-lead { font-size: calc(var(--type-lg) * 1.1); line-height: 1.5; color: var(--lp-ink-2); max-width: 34em; }

/* ── buttons ──────────────────────────────────────────────────────────── */
.lp-btn {
  display: inline-flex; align-items: center; justify-content: center;
  min-height: 44px; padding: 0 var(--space-6);
  border: 1px solid transparent; border-radius: var(--radius-md);
  font: inherit; font-size: var(--type-base); font-weight: var(--weight-semibold);
  cursor: pointer; white-space: nowrap;
  transition: background var(--dur-soft) var(--ease-out), color var(--dur-soft) var(--ease-out), border-color var(--dur-soft) var(--ease-out);
}
.lp-btn:focus-visible { outline: 2px solid var(--lp-clay); outline-offset: 2px; }
.lp-btn--primary { background: var(--lp-clay); color: var(--lp-cream); }
.lp-btn--primary:hover { background: var(--lp-clay-hi); }
.lp-btn--ghost { border-color: var(--lp-ink); color: var(--lp-ink); background: transparent; }
.lp-btn--ghost:hover { background: var(--lp-ink); color: var(--lp-cream); }
.lp-btn--light { background: var(--lp-cream); color: var(--lp-ink); }
.lp-btn--light:hover { background: var(--lp-paper); }
.lp-btn--sm { min-height: 44px; padding: 0 var(--space-5); }

/* ── beans and bags (flat shapes, no photos yet) ──────────────────────── */
.lp-bean ellipse { fill: currentColor; }
.lp-bean path { fill: none; stroke: var(--bean-line, var(--lp-cream)); stroke-width: 3; stroke-linecap: round; }

.lp-bag {
  --lbl-bg: var(--lp-cream); --lbl-fg: var(--lp-ink);
  width: 100%; aspect-ratio: 3 / 4.2;
  display: flex; flex-direction: column;
  border-radius: var(--radius-md); overflow: hidden;
  background: var(--lp-clay);
}
.lp-bag--clay  { background: var(--lp-clay); }
.lp-bag--ink   { background: var(--lp-espresso); }
.lp-bag--crema { background: var(--lp-crema); --lbl-bg: var(--lp-espresso); --lbl-fg: var(--lp-cream); }
.lp-bag-fold { flex: none; height: 9%; background: var(--lp-ink); opacity: 0.85; }
.lp-bag-label {
  margin: auto; width: 66%; padding: var(--space-5) var(--space-3);
  display: grid; justify-items: center; gap: var(--space-3);
  background: var(--lbl-bg); color: var(--lbl-fg); border-radius: var(--radius-sm);
}
.lp-bag-bean { width: 22%; height: auto; --bean-line: var(--lbl-bg); }
.lp-bag-rule { display: block; width: 70%; height: 3px; border-radius: var(--radius-pill); background: currentColor; opacity: 0.55; }
.lp-bag-rule--short { width: 44%; }

/* ── header ───────────────────────────────────────────────────────────── */
.lp-hd {
  display: flex; align-items: center; justify-content: space-between; gap: var(--space-6);
  padding-block: var(--space-5);
  border-bottom: 1px solid var(--lp-line);
}
.lp-brand { display: inline-flex; align-items: center; gap: var(--space-3); color: var(--lp-roast); }
.lp-brand-bean { width: 18px; height: auto; }
.lp-brand-name { font-family: var(--font-display); font-size: var(--type-lg); font-weight: var(--weight-bold); letter-spacing: var(--tracking-tight); color: var(--lp-ink); }
.lp-nav { display: flex; gap: var(--space-6); margin-inline: auto var(--space-6); }
.lp-nav a { font-size: var(--type-base); font-weight: var(--weight-medium); color: var(--lp-ink-2); padding-block: var(--space-3); }
.lp-nav a:hover { color: var(--lp-ink); }

/* ── hero ─────────────────────────────────────────────────────────────── */
.lp-hero {
  display: grid; grid-template-columns: 1.05fr 0.95fr; gap: var(--space-8); align-items: center;
  padding-block: calc(var(--space-8) * 1.25);
}
.lp-hero-copy { display: grid; gap: var(--space-5); justify-items: start; }
.lp-actions { display: flex; flex-wrap: wrap; gap: var(--space-4); margin-top: var(--space-3); }
.lp-hero-art {
  position: relative; overflow: hidden;
  aspect-ratio: 1 / 1.08;
  display: grid; place-items: center;
  background: var(--lp-roast); border-radius: var(--radius-xl);
}
.lp-hero-bag { width: 42%; z-index: 1; }
.lp-hero-bean { position: absolute; height: auto; color: var(--lp-latte); }
.lp-hero-bean--1 { width: 9%;  left: 10%; top: 12%; transform: rotate(-24deg); }
.lp-hero-bean--2 { width: 12%; right: 11%; top: 9%;  transform: rotate(32deg); color: var(--lp-clay); }
.lp-hero-bean--3 { width: 8%;  left: 17%; bottom: 20%; transform: rotate(58deg); color: var(--lp-crema); }
.lp-hero-bean--4 { width: 11%; right: 14%; bottom: 24%; transform: rotate(-48deg); }
.lp-hero-bean--5 { width: 7%;  right: 31%; top: 16%; transform: rotate(12deg); color: var(--lp-crema); }
.lp-stamp {
  position: absolute; left: var(--space-6); bottom: var(--space-6); z-index: 2;
  display: inline-flex; align-items: center; gap: var(--space-3);
  padding: var(--space-3) var(--space-5);
  background: var(--lp-cream); color: var(--lp-ink); border-radius: var(--radius-pill);
  font-size: var(--type-sm); line-height: var(--lh-sm); font-weight: var(--weight-semibold);
}
.lp-stamp-dot { width: 8px; height: 8px; border-radius: var(--radius-pill); background: var(--lp-clay); }

/* ── facts strip ──────────────────────────────────────────────────────── */
.lp-facts { display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--space-6); padding-block: var(--space-7); border-top: 1px solid var(--lp-line); border-bottom: 1px solid var(--lp-line); }
.lp-fact { display: grid; gap: var(--space-2); }
.lp-fact-num { font-family: var(--font-display); font-size: var(--type-2xl); line-height: var(--lh-2xl); font-weight: var(--weight-semibold); letter-spacing: var(--tracking-tight); }
.lp-fact-text { font-size: var(--type-base); line-height: var(--lh-base); color: var(--lp-ink-2); }

/* ── this week's coffees ──────────────────────────────────────────────── */
.lp-coffees { background: var(--lp-paper); padding-block: calc(var(--space-8) * 1.5); display: grid; gap: var(--space-7); }
.lp-sec-hd { display: grid; gap: var(--space-3); max-width: 28em; }
.lp-cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--space-6); }
.lp-card { display: flex; flex-direction: column; background: var(--lp-cream); border: 1px solid var(--lp-line); border-radius: var(--radius-lg); overflow: hidden; }
.lp-card-art { display: grid; place-items: center; aspect-ratio: 4 / 3; padding-block: var(--space-6); }
.lp-card-art--1 { background: var(--lp-crema); }
.lp-card-art--2 { background: var(--lp-latte); }
.lp-card-art--3 { background: var(--lp-roast); }
.lp-card-bag { height: 100%; aspect-ratio: 3 / 4.2; }
.lp-card-body { flex: 1; display: flex; flex-direction: column; gap: var(--space-3); padding: var(--space-6); }
.lp-card-origin { font-family: var(--font-mono); font-size: var(--type-sm); line-height: var(--lh-sm); letter-spacing: var(--tracking-wide); text-transform: uppercase; color: var(--lp-ink-2); }
.lp-card-notes { font-size: var(--type-base); line-height: var(--lh-base); color: var(--lp-ink-2); }
.lp-card-foot { margin-top: auto; padding-top: var(--space-5); display: flex; align-items: center; justify-content: space-between; gap: var(--space-4); }
.lp-card-price { font-family: var(--font-mono); font-size: var(--type-base); font-weight: var(--weight-medium); font-variant-numeric: tabular-nums; }

/* ── story ────────────────────────────────────────────────────────────── */
.lp-story { background: var(--lp-espresso); color: var(--lp-cream); display: grid; grid-template-columns: 1fr 1fr; gap: var(--space-8); padding-block: calc(var(--space-8) * 1.5); align-items: start; }
.lp-story-copy { display: grid; gap: var(--space-5); }
.lp-story .lp-eyebrow { color: var(--lp-latte); }
.lp-story-text { font-size: calc(var(--type-lg) * 1.05); line-height: 1.55; color: var(--lp-cream-2); max-width: 30em; }
.lp-steps { border-top: 1px solid var(--lp-roast); }
.lp-step { display: grid; grid-template-columns: auto 1fr; column-gap: var(--space-6); row-gap: var(--space-2); padding-block: var(--space-6); border-bottom: 1px solid var(--lp-roast); }
.lp-step-num { grid-row: span 2; font-family: var(--font-mono); font-size: var(--type-base); color: var(--lp-latte); padding-top: var(--space-2); font-variant-numeric: tabular-nums; }
.lp-step-text { font-size: var(--type-base); line-height: var(--lh-base); color: var(--lp-cream-2); }

/* ── subscription band ────────────────────────────────────────────────── */
.lp-sub { background: var(--lp-clay); color: var(--lp-cream); display: flex; align-items: center; justify-content: space-between; gap: var(--space-7); padding-block: var(--space-8); }
.lp-sub-copy { display: grid; gap: var(--space-3); max-width: 34em; }
.lp-sub-text { font-size: var(--type-md); line-height: var(--lh-md); }

/* ── visit ────────────────────────────────────────────────────────────── */
.lp-visit { display: grid; grid-template-columns: 1fr 1fr; gap: var(--space-8); align-items: center; padding-block: calc(var(--space-8) * 1.5); }
.lp-visit-copy { display: grid; gap: var(--space-5); justify-items: start; }
.lp-address { font-size: var(--type-lg); line-height: var(--lh-lg); font-weight: var(--weight-medium); }
.lp-hours { display: grid; grid-template-columns: auto 1fr; gap: var(--space-3) var(--space-6); font-size: var(--type-base); line-height: var(--lh-base); }
.lp-hours dt { color: var(--lp-ink-2); }
.lp-hours dd { font-family: var(--font-mono); font-variant-numeric: tabular-nums; }
.lp-map { aspect-ratio: 5 / 4; border-radius: var(--radius-xl); overflow: hidden; background: var(--lp-paper); border: 1px solid var(--lp-line); }
.lp-map svg { display: block; width: 100%; height: 100%; }
.lp-map-block { fill: var(--lp-cream); }
.lp-map-road { fill: none; stroke: var(--lp-crema); stroke-width: 10; stroke-linecap: round; }
.lp-map-road--thin { stroke-width: 5; stroke: var(--lp-line); }
.lp-map-pin { fill: var(--lp-clay); }
.lp-map-pin-dot { fill: var(--lp-cream); }

/* ── footer ───────────────────────────────────────────────────────────── */
.lp-ft { display: flex; align-items: center; justify-content: space-between; gap: var(--space-6); padding-block: var(--space-6); border-top: 1px solid var(--lp-line); font-size: var(--type-sm); line-height: var(--lh-sm); color: var(--lp-ink-2); }
.lp-ft-links { display: flex; gap: var(--space-6); }
.lp-ft-links a { padding-block: var(--space-3); }
.lp-ft-links a:hover { color: var(--lp-ink); }

/* ── tablet: the page narrows ─────────────────────────────────────────── */
@container lp (max-width: 1000px) {
  .lp-h1 { font-size: calc(var(--type-3xl) * 1.5); }
  .lp-h2 { font-size: var(--type-3xl); line-height: var(--lh-3xl); }
  .lp-hero { gap: var(--space-7); padding-block: var(--space-8); }
  .lp-nav { gap: var(--space-5); }
  .lp-cards { gap: var(--space-4); }
  .lp-card-body { padding: var(--space-5); }
  .lp-card-foot { flex-wrap: wrap; }
  .lp-story, .lp-visit { gap: var(--space-7); }
}

/* ── mobile: one column ───────────────────────────────────────────────── */
@container lp (max-width: 720px) {
  .lp-nav { display: none; }
  .lp-h1 { font-size: calc(var(--type-3xl) * 1.2); }
  .lp-h2 { font-size: var(--type-2xl); line-height: var(--lh-2xl); }
  .lp-lead { font-size: var(--type-md); }
  .lp-hero { grid-template-columns: 1fr; gap: var(--space-7); padding-block: var(--space-7); }
  .lp-hero-art { aspect-ratio: 4 / 3.4; }
  .lp-hero-bag { width: 36%; }
  .lp-facts { grid-template-columns: 1fr; gap: var(--space-5); padding-block: var(--space-6); }
  .lp-coffees, .lp-story, .lp-visit { padding-block: var(--space-8); }
  .lp-cards { grid-template-columns: 1fr; gap: var(--space-5); }
  .lp-card-art { aspect-ratio: 16 / 10; padding-block: var(--space-5); }
  .lp-story, .lp-visit { grid-template-columns: 1fr; gap: var(--space-7); }
  .lp-sub { flex-direction: column; align-items: flex-start; gap: var(--space-6); padding-block: var(--space-7); }
  .lp-ft { flex-direction: column; align-items: flex-start; gap: var(--space-4); }
}

